        (52696, ARRAY[52696,52695,52694,52693], ARRAY[300000,300000,300000,300000]::BIGINT[]),
        (52853, ARRAY[52853,52852,52851,52850], ARRAY[300000,300000,300000,300000]::BIGINT[]),
